+    for (int j = 0; j < q->nlines; j++) free(q->lines[j].p);
+  }
+  qix_free_upstream(dpy, window, closure);
+}
+
+const HackEntry qix_hack = {"Qix", qix_defaults, qix_init, qix_draw, qix_free,
+                            NULL, NULL};
