1:#ifndef HACKS_FLOAT_POLYGON_H
2:#define HACKS_FLOAT_POLYGON_H
3:
4:#include <math.h>
5:#include <stdint.h>
6:#include <stdlib.h>
7:
8:#include "core/canvas.h"
9:#include "x11shim/pixmap.h"
10:#include "x11shim/xshim.h"
11:
12:/* Fills any polygon even-odd (a self-crossing outline leaves a hole), in
13: * float, for a hack whose wrapper maps XFillPolygon onto it. The shim's
14: * canvas_fill_polygon divides in double for every edge on every row, which the
15: * S3 does in software. This keeps an edge table sorted by starting row and
16: * steps each edge's x by its slope, so there is no division per row.
17: *
18: * A pixel is filled when its centre is inside, as the shim does it. Edges
19: * crossing exactly at a half pixel can round to the neighbouring pixel. */
20:typedef struct {
21:  float x, slope;
22:  int y0, y1; /* the edge crosses rows y0 <= y < y1 */
23:} FloatEdge;
24:
25:static int float_edge_order(const void *a, const void *b) {
26:  const FloatEdge *ea = *(const FloatEdge *const *)a, *eb = *(const FloatEdge *const *)b;
27:  return (ea->y0 > eb->y0) - (ea->y0 < eb->y0);
28:}
29:
30:/* One row's span [xa, xb] mixed with what is there. The canvas holds byte
31: * swapped RGB565, so each pixel is unswapped, and all three channels are mixed
32: * at once: spreading a pixel's fields apart (red at bit 11, blue at bit 0,
33: * green at bit 21, with room between them) lets one multiply weight them all,
34: * `alpha` parts in 32 of the new colour and the rest of the old. Each field's
35: * sum fits its own bit range and the shift drops the low bits, so the result
36: * is the per-channel (new * alpha + old * (32 - alpha)) / 32, rounded down. */
37:#define FLOAT_FIELDS 0x07E0F81Fu
38:
39:static void float_blend_span(Canvas *c, int xa, int xb, int y, uint16_t color, int alpha) {
40:  if (y < 0 || y >= c->h || xb < 0 || xa >= c->w) return;
41:  if (xa < 0) xa = 0;
42:  if (xb >= c->w) xb = c->w - 1;
43:  if (xa > xb) return;
44:  const uint32_t src = px_swap(color);
45:  const uint32_t weighted = ((src | (src << 16)) & FLOAT_FIELDS) * (uint32_t)alpha;
46:  const uint32_t inv = (uint32_t)(32 - alpha);
47:  uint16_t *row = c->px + (size_t)y * (size_t)c->w;
48:  for (int x = xa; x <= xb; x++) {
49:    const uint32_t d = px_swap(row[x]);
50:    const uint32_t mixed = ((weighted + ((d | (d << 16)) & FLOAT_FIELDS) * inv) >> 5) & FLOAT_FIELDS;
51:    row[x] = px_swap((uint16_t)(mixed | (mixed >> 16)));
52:  }
53:  canvas_mark_dirty(c, xa, y, xb - xa + 1, 1);
54:}
55:
56:/* As float_fill_polygon, but the colour is mixed in: `alpha` is in 32nds,
57: * 32 opaque and 0 nothing. */
58:static void float_fill_polygon_alpha(Canvas *c, const XPoint *pts, int n, uint16_t color, int alpha) {
59:  if (!pts || n < 3 || alpha <= 0) return;
60:  if (alpha > 32) alpha = 32;
61:  FloatEdge stack_edges[128];
62:  FloatEdge *edges = stack_edges;
63:  const FloatEdge *stack_order[128];
64:  const FloatEdge **order = stack_order;
65:  const FloatEdge *stack_active[128];
66:  const FloatEdge **active = stack_active;
67:  float stack_xs[128];
68:  float *xs = stack_xs;
69:  FloatEdge **heap = NULL;
70:  if (n > 128) {
71:    heap = (FloatEdge **)malloc((size_t)n * (sizeof(FloatEdge) + 3 * sizeof(void *) + sizeof(float)));
72:    if (!heap) return;
73:    edges = (FloatEdge *)heap;
74:    order = (const FloatEdge **)(edges + n);
75:    active = order + n;
76:    xs = (float *)(active + n);
77:  }
78:  int ne = 0, ymin = INT32_MAX, ymax = INT32_MIN;
79:  for (int i = 0, j = n - 1; i < n; j = i++) {
80:    int xa = pts[j].x, ya = pts[j].y, xb = pts[i].x, yb = pts[i].y;
81:    if (ya == yb) continue;
82:    if (ya > yb) {
83:      const int tx = xa, ty = ya;
84:      xa = xb, ya = yb, xb = tx, yb = ty;
85:    }
86:    FloatEdge *e = &edges[ne++];
87:    e->slope = (float)(xb - xa) / (float)(yb - ya);
88:    e->y0 = ya;
89:    e->y1 = yb;
90:    e->x = (float)xa + 0.5f * e->slope; /* at the centre of row ya */
91:    if (ya < ymin) ymin = ya;
92:    if (yb > ymax) ymax = yb;
93:  }
94:  if (ne >= 2) {
95:    for (int i = 0; i < ne; i++) order[i] = &edges[i];
96:    qsort(order, (size_t)ne, sizeof(order[0]), float_edge_order);
97:    int y = ymin < 0 ? 0 : ymin;
98:    const int last = ymax > c->h ? c->h : ymax;
99:    int next = 0, na = 0;
100:    for (; y < last; y++) {
101:      while (next < ne && order[next]->y0 <= y) {
102:        FloatEdge *e = (FloatEdge *)order[next++];
103:        if (e->y0 < y) e->x += e->slope * (float)(y - e->y0);
104:        active[na++] = e;
105:      }
106:      int nx = 0;
107:      for (int k = 0; k < na;) {
108:        FloatEdge *e = (FloatEdge *)active[k];
109:        if (y >= e->y1) {
110:          active[k] = active[--na];
111:          continue;
112:        }
113:        float v = e->x;
114:        e->x += e->slope;
115:        int m = nx++;
116:        while (m > 0 && xs[m - 1] > v) {
117:          xs[m] = xs[m - 1];
118:          m--;
119:        }
120:        xs[m] = v;
121:        k++;
122:      }
123:      for (int k = 0; k + 1 < nx; k += 2) {
124:        const int xa = (int)ceilf(xs[k] - 0.5f);
125:        const int xb = (int)ceilf(xs[k + 1] - 0.5f) - 1;
126:        if (xb >= xa) {
127:          if (alpha >= 32)
128:            canvas_fill_rect(c, xa, y, xb - xa + 1, 1, color);
129:          else
130:            float_blend_span(c, xa, xb, y, color, alpha);
131:        }
132:      }
133:    }
134:  }
135:  free(heap);
136:}
137:
138:static void float_fill_polygon(Canvas *c, const XPoint *pts, int n, uint16_t color) {
139:  float_fill_polygon_alpha(c, pts, n, color, 32);
140:}
141:
142:/* XFillPolygon's arguments, for a wrapper to `#define XFillPolygon` onto: the
143: * shape and mode are ignored, as the shim's are. A bitmap or None draws
144: * nothing. */
145:static int float_x_fill_polygon(Display *dpy, Drawable d, GC gc, XPoint *pts,
146:                                int n, int shape, int mode) {
147:  (void)shape, (void)mode;
148:  Canvas *c = xshim_target(dpy, d);
149:  if (c) float_fill_polygon(c, pts, n, (uint16_t)gc->foreground);
150:  return 0;
151:}
152:
153:#endif

